            panel.updateMemberCount(12);
            refreshVitals();
            panel.updateCombatStats(99, 99, 99, 99, 99, 99, 99, 99, 99, 99);
            panel.updateOpponent("Zulrah", 180, 255);
            panel.updateGameMessage("Click an item to use it!");
            panel.updateEffects(activeEffects);

            // ── Build the window ──────────────────────────────────────
            JFrame frame = new JFrame("Big Goblins — Preview");
            frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            frame.getContentPane().setBackground(new Color(30, 27, 22));
            frame.setLayout(new BorderLayout(8, 0));

            // Left: fake inventory area
            JPanel leftPanel = buildInventoryPanel();
            frame.add(leftPanel, BorderLayout.WEST);

            // Right: the actual plugin panel
            JScrollPane scroll = new JScrollPane(panel);
            scroll.setPreferredSize(new Dimension(242, 720));
            scroll.setBorder(null);
            scroll.setBackground(new Color(40, 40, 40));
            scroll.getVerticalScrollBar().setUnitIncrement(8);
            frame.add(scroll, BorderLayout.CENTER);

            // Bottom: status bar
            statusLabel = new JLabel("  Ready — select a loadout and click items to test");
            statusLabel.setForeground(new Color(180, 180, 180));
            statusLabel.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
            statusLabel.setBorder(new EmptyBorder(4, 8, 4, 8));
            statusLabel.setBackground(new Color(20, 18, 14));
            statusLabel.setOpaque(true);
            frame.add(statusLabel, BorderLayout.SOUTH);

            frame.pack();
            frame.setLocationRelativeTo(null);
            frame.setVisible(true);
        });
    }

    // ── Inventory + loadout selector ─────────────────────────────
    private static JPanel buildInventoryPanel()
    {
        JPanel wrapper = new JPanel(new BorderLayout(0, 6));
        wrapper.setBackground(new Color(30, 27, 22));
        wrapper.setBorder(new EmptyBorder(8, 8, 8, 4));

        // Loadout selector buttons
        JPanel loadoutBar = new JPanel(new FlowLayout(FlowLayout.CENTER, 4, 0));
        loadoutBar.setBackground(new Color(30, 27, 22));

        FakeInventory inventory = new FakeInventory(PanelPreview::onItemUsed);

        JButton pvpBtn  = loadoutButton("PvP",     () -> inventory.loadItems(Loadouts.pvp()));
        JButton pvmBtn  = loadoutButton("PvM",     () -> inventory.loadItems(Loadouts.pvm()));
        JButton skilBtn = loadoutButton("Skilling",() -> inventory.loadItems(Loadouts.skilling()));
        JButton clrBtn  = loadoutButton("Clear",   () ->
        {
            activeEffects.clear();
            panel.updateEffects(activeEffects);
            hp = 99; prayer = 77; spec = 100;
            refreshVitals();
            status("Stats reset.");
        });

        loadoutBar.add(pvpBtn);
        loadoutBar.add(pvmBtn);
        loadoutBar.add(skilBtn);
        loadoutBar.add(clrBtn);

        // Title
        JLabel title = new JLabel("INVENTORY", SwingConstants.CENTER);
        title.setForeground(new Color(200, 180, 120));
        title.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 11));
        title.setBorder(new EmptyBorder(0, 0, 4, 0));

        JPanel top = new JPanel(new BorderLayout());
        top.setBackground(new Color(30, 27, 22));
        top.add(title, BorderLayout.NORTH);
        top.add(loadoutBar, BorderLayout.CENTER);

        wrapper.add(top, BorderLayout.NORTH);
        wrapper.add(inventory, BorderLayout.CENTER);

        // Load PvM by default
        inventory.loadItems(Loadouts.pvm());

        return wrapper;
    }

    private static JButton loadoutButton(String label, Runnable action)
    {
        JButton btn = new JButton(label);
        btn.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
        btn.setForeground(new Color(220, 200, 140));
        btn.setBackground(new Color(60, 53, 42));
        btn.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(new Color(100, 90, 60), 1),
            new EmptyBorder(3, 8, 3, 8)
        ));
        btn.setFocusPainted(false);
        btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        btn.addActionListener(e -> action.run());
        return btn;
    }

    // ── Item use handler ─────────────────────────────────────────
    private static void onItemUsed(FakeItem item)
    {
        StringBuilder msg = new StringBuilder("Used: ").append(item.name);

        // Restore HP
        if (item.hpRestore > 0)
        {
            hp = Math.min(maxHp, hp + item.hpRestore);
            msg.append("  +").append(item.hpRestore).append(" HP");
        }

        // Restore Prayer
        if (item.prayerRestore > 0)
        {
            prayer = Math.min(maxPray, prayer + item.prayerRestore);
            msg.append("  +").append(item.prayerRestore).append(" Prayer");
        }

        // Restore Spec
        if (item.specRestore > 0)
        {
            spec = Math.min(100, spec + item.specRestore);
            msg.append("  +").append(item.specRestore).append("% Spec");
        }

        // Add effect
        if (item.effectName != null)
        {
            activeEffects.put(item.effectName, new int[]{item.id, item.effectTicks});
            panel.updateEffects(activeEffects);
            msg.append("  → ").append(item.effectName).append(" active");
        }

        refreshVitals();
        panel.updateGameMessage(msg.toString());
        status(msg.toString());
    }

    private static void refreshVitals()
    {
        panel.updateHitpoints(hp, maxHp);
        panel.updatePrayer(prayer, maxPray);
        panel.updateSpecial(spec);
    }

    private static void status(String text)
    {
        if (statusLabel != null)
            statusLabel.setText("  " + text);
    }

    /** Coloured placeholder for item icons (no RuneLite needed). */
    private static BufferedImage stubItemImage(int itemId)
    {
        BufferedImage img = new BufferedImage(24, 22, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        int hue = (itemId * 47) % 360;
        g.setColor(Color.getHSBColor(hue / 360f, 0.6f, 0.7f));
        g.fillRoundRect(2, 2, 20, 18, 4, 4);
        g.setColor(new Color(255, 255, 255, 160));
        g.setFont(new Font(Font.MONOSPACED, Font.BOLD, 6));
        g.drawString("ITM", 4, 14);
        g.dispose();
        return img;
    }
}

package com.biggoblins;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;

/**
 * A custom retro-styled progress bar with pixel aesthetics,
 * inner glow, and text overlay.
 */
public class RetroProgressBar extends JComponent
{
	private static final Color TRACK_BG = new Color(15, 15, 15);
	private static final Color TRACK_BORDER_OUTER = new Color(10, 10, 10);
	private static final Color TRACK_BORDER_INNER = new Color(50, 50, 50);
	private static final Color TEXT_SHADOW = new Color(0, 0, 0, 200);

	private int value;
	private int maxValue;
	private Color barColorStart;
	private Color barColorEnd;
	private String label;
	private Font textFont;
	private boolean percentMode;

	public RetroProgressBar(String label, Color barColorStart, Color barColorEnd)
	{
		this.label = label;
		this.barColorStart = barColorStart;
		this.barColorEnd = barColorEnd;
		this.value = 0;
		this.maxValue = 1;
		this.textFont = new Font(Font.MONOSPACED, Font.BOLD, 12);
		setPreferredSize(new Dimension(0, 24));
		setMinimumSize(new Dimension(50, 24));
	}

	public void update(int value, int maxValue)
	{
		this.value = value;
		this.maxValue = Math.max(maxValue, 1);
		repaint();
	}

	public void setPercentMode(boolean percentMode)
	{
		this.percentMode = percentMode;
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		int w = getWidth();
		int h = getHeight();

		// Outer border (dark inset)
		g2.setColor(TRACK_BORDER_OUTER);
		g2.fillRect(0, 0, w, h);

		// Inner border highlight (subtle top-left light)
		g2.setColor(TRACK_BORDER_INNER);
		g2.drawRect(1, 1, w - 3, h - 3);

		// Track background
		g2.setColor(TRACK_BG);
		g2.fillRect(2, 2, w - 4, h - 4);

		// Calculate fill
		float percent = Math.min(1.0f, (float) value / maxValue);
		int fillWidth = (int) ((w - 4) * percent);

		if (fillWidth > 0)
		{
			// Gradient bar fill
			GradientPaint gradient = new GradientPaint(
				2, 2, barColorStart,
				2, h - 4, barColorEnd
			);
			g2.setPaint(gradient);
			g2.fillRect(2, 2, fillWidth, h - 4);

			// Top highlight shine (inner glow)
			Color shine = new Color(255, 255, 255, 60);
			g2.setColor(shine);
			g2.fillRect(2, 2, fillWidth, (h - 4) / 3);

			// Bottom edge darkening
			Color bottomShade = new Color(0, 0, 0, 50);
			g2.setColor(bottomShade);
			g2.fillRect(2, h - 4, fillWidth, 2);

			// Pixel notches every 10% for retro feel
			g2.setColor(new Color(0, 0, 0, 40));
			for (int i = 1; i < 10; i++)
			{
				int notchX = 2 + (int) ((w - 4) * (i / 10.0));
				if (notchX < 2 + fillWidth)
				{
					g2.drawLine(notchX, 2, notchX, h - 3);
				}
			}
		}

		// Text overlay: "value / max"
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		g2.setFont(textFont);
		String text;
		if (percentMode)
		{
			int pct = maxValue > 0 ? Math.round((float) value / maxValue * 100) : 0;
			text = pct + "%";
		}
		else
		{
			text = value + " / " + maxValue;
		}
		FontMetrics fm = g2.getFontMetrics();
		int textX = (w - fm.stringWidth(text)) / 2;
		int textY = (h + fm.getAscent() - fm.getDescent()) / 2;

		// Text shadow
		g2.setColor(TEXT_SHADOW);
		g2.drawString(text, textX + 1, textY + 1);

		// Text foreground
		g2.setColor(Color.WHITE);
		g2.drawString(text, textX, textY);

		g2.dispose();
	}
}

package com.biggoblins.preview;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.function.Consumer;

/**
 * Fake OSRS-style inventory grid (4 cols x 7 rows = 28 slots).
 * Clicking an item fires the onItemUsed consumer.
 */
public class FakeInventory extends JPanel
{
    private static final int COLS      = 4;
    private static final int ROWS      = 7;
    private static final int SLOT_SIZE = 50;
    private static final Color BG      = new Color(60, 53, 42);       // OSRS inventory brown
    private static final Color SLOT_BG = new Color(75, 67, 53);
    private static final Color HOVER   = new Color(100, 90, 70);
    private static final Color SELECT  = new Color(200, 170, 80, 120);
    private static final Color BORDER  = new Color(40, 35, 28);

    private final SlotPanel[] slots = new SlotPanel[COLS * ROWS];
    private final Consumer<FakeItem> onItemUsed;
    private int selectedSlot = -1;

    public FakeInventory(Consumer<FakeItem> onItemUsed)
    {
        this.onItemUsed = onItemUsed;
        setBackground(BG);
        setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(new Color(30, 25, 18), 2),
            new EmptyBorder(4, 4, 4, 4)
        ));
        setLayout(new GridLayout(ROWS, COLS, 2, 2));

        for (int i = 0; i < COLS * ROWS; i++)
        {
            SlotPanel slot = new SlotPanel(i);
            slots[i] = slot;
            add(slot);
        }
    }

    public void loadItems(List<FakeItem> items)
    {
        selectedSlot = -1;
        for (int i = 0; i < COLS * ROWS; i++)
        {
            FakeItem item = (i < items.size()) ? items.get(i) : null;
            slots[i].setItem(item);
        }
        repaint();
    }

    // ── Slot panel ────────────────────────────────────────────────
    private class SlotPanel extends JPanel
    {
        private final int index;
        private FakeItem item;
        private boolean hovered;

        SlotPanel(int index)
        {
            this.index = index;
            setPreferredSize(new Dimension(SLOT_SIZE, SLOT_SIZE));
            setBackground(SLOT_BG);
            setOpaque(false);

            addMouseListener(new MouseAdapter()
            {
                @Override public void mouseEntered(MouseEvent e) { hovered = true;  repaint(); }
                @Override public void mouseExited(MouseEvent e)  { hovered = false; repaint(); }
                @Override public void mouseClicked(MouseEvent e)
                {
                    if (item == null) return;
                    selectedSlot = index;
                    repaint();
                    onItemUsed.accept(item);

                    // Flash selection off after 300ms
                    Timer t = new Timer(300, ev -> { selectedSlot = -1; repaint(); });
                    t.setRepeats(false);
                    t.start();
                }
            });
        }

        void setItem(FakeItem i) { this.item = i; repaint(); }

        @Override
        protected void paintComponent(Graphics g)
        {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            int w = getWidth(), h = getHeight();

            // Slot background
            g2.setColor(hovered && item != null ? HOVER : SLOT_BG);
            g2.fillRect(0, 0, w, h);

            // Slot border
            g2.setColor(BORDER);
            g2.drawRect(0, 0, w - 1, h - 1);

            if (item != null)
            {
                // Draw coloured item icon
                drawItemIcon(g2, item, w, h);

                // Selection highlight
                if (selectedSlot == index)
                {
                    g2.setColor(SELECT);
                    g2.fillRect(0, 0, w, h);
                }

                // Item quantity dots on corner (visual flair)
                g2.setColor(new Color(255, 255, 255, 60));
                g2.fillOval(w - 8, 2, 5, 5);
            }

            g2.dispose();
        }

        private void drawItemIcon(Graphics2D g2, FakeItem it, int w, int h)
        {
            // Draw a stylised item placeholder icon
            int iconW = 36, iconH = 32;
            int x = (w - iconW) / 2;
            int y = (h - iconH) / 2 - 2;

            // Shadow
            g2.setColor(new Color(0, 0, 0, 80));
            g2.fillRoundRect(x + 2, y + 2, iconW, iconH, 6, 6);

            // Main colour block
            g2.setColor(it.color);
            g2.fillRoundRect(x, y, iconW, iconH, 6, 6);

            // Highlight shine
            g2.setColor(new Color(255, 255, 255, 50));
            g2.fillRoundRect(x + 3, y + 2, iconW - 6, iconH / 2, 4, 4);

            // Short name text
            g2.setColor(Color.WHITE);
            g2.setFont(new Font(Font.MONOSPACED, Font.BOLD, 9));
            FontMetrics fm = g2.getFontMetrics();
            int tx = x + (iconW - fm.stringWidth(it.shortName)) / 2;
            int ty = y + (iconH + fm.getAscent()) / 2 - 2;
            // shadow
            g2.setColor(new Color(0, 0, 0, 180));
            g2.drawString(it.shortName, tx + 1, ty + 1);
            g2.setColor(Color.WHITE);
            g2.drawString(it.shortName, tx, ty);

            // Type indicator pip
            Color pipColor;
            switch (it.type)
            {
                case POTION: pipColor = new Color(100, 220, 100); break;
                case EFFECT: pipColor = new Color(220, 100, 100); break;
                case FOOD:   pipColor = new Color(220, 180, 80);  break;
                default:     pipColor = new Color(150, 150, 150); break;
            }
            g2.setColor(pipColor);
            g2.fillOval(x + 2, y + iconH - 8, 6, 6);
        }
    }
}

package com.biggoblins.preview;

import java.awt.Color;

/**
 * Represents a fake OSRS item for the preview inventory.
 */
public class FakeItem
{
    public enum Type { POTION, EFFECT, GEAR, FOOD, OTHER }

    public final int id;
    public final String name;
    public final Type type;
    public final Color color;       // icon placeholder colour
    public final String shortName;  // 3-char icon label

    // Potion/food effect fields
    public final int hpRestore;
    public final int prayerRestore;
    public final int specRestore;

    // Effect fields
    public final String effectName;
    public final int effectTicks;

    private FakeItem(Builder b)
    {
        this.id            = b.id;
        this.name          = b.name;
        this.type          = b.type;
        this.color         = b.color;
        this.shortName     = b.shortName;
        this.hpRestore     = b.hpRestore;
        this.prayerRestore = b.prayerRestore;
        this.specRestore   = b.specRestore;
        this.effectName    = b.effectName;
        this.effectTicks   = b.effectTicks;
    }

    public static Builder builder(int id, String name, Type type)
    {
        return new Builder(id, name, type);
    }

    public static class Builder
    {
        int id; String name; Type type;
        Color color = new Color(120, 120, 180);
        String shortName = "ITM";
        int hpRestore, prayerRestore, specRestore;
        String effectName; int effectTicks;

        Builder(int id, String name, Type type) { this.id = id; this.name = name; this.type = type; }
        public Builder color(Color c)           { this.color = c; return this; }
        public Builder shortName(String s)      { this.shortName = s; return this; }
        public Builder hp(int v)                { this.hpRestore = v; return this; }
        public Builder prayer(int v)            { this.prayerRestore = v; return this; }
        public Builder spec(int v)              { this.specRestore = v; return this; }
        public Builder effect(String n, int t)  { this.effectName = n; this.effectTicks = t; return this; }
        public FakeItem build()                 { return new FakeItem(this); }
    }
}

